namespace ark::es2panda::compiler::ast_verifier {

CheckResult EveryChildHasValidParent::operator()(const ir::AstNode *ast)
{
    auto result = std::make_tuple(CheckDecision::CORRECT, CheckAction::CONTINUE);
    if (ast->IsETSModule()) {
        return result;
    }

    auto maybeOverloadMethod = [](const ir::AstNode *root, const ir::AstNode *node) -> bool {
        if ((root->IsClassDefinition() || root->IsTSInterfaceBody()) && node->IsMethodDefinition() &&
            node->Parent()->IsMethodDefinition()) {
            auto maybeBaseOverloadMethod = node->Parent()->AsMethodDefinition();
            auto overloads = maybeBaseOverloadMethod->Overloads();
            auto res =
                std::find_if(overloads.begin(), overloads.end(), [node](ir::MethodDefinition *m) { return m == node; });
            return res != overloads.end() || maybeBaseOverloadMethod->AsyncPairMethod() == node;
        }
        return false;
    };

    ast->Iterate([this, ast, maybeOverloadMethod, &result](const ir::AstNode *node) {
        if (ir::AstNode const *parent = node->Parent(); ast != parent) {
            //  NOTE: Temporary suppress.
            //  Should be removed after proper overload method's parent setting
            //  For now there is no right decision who is parent of overload method:
            //  baseOverloadMethod or ClassDefininiton, but the first is set
            if (maybeOverloadMethod(ast, node)) {
                return;
            }

            AddCheckMessage("INCORRECT_PARENT_REF", *node);
            result = {CheckDecision::INCORRECT, CheckAction::CONTINUE};
        }
    });

    return result;
}

}  // namespace ark::es2panda::compiler::ast_verifier

## Phases in `es2panda` as of 2024.10.20

- `plugins-after-parse`: call compiler plugins that work immediately after parsing, if any.

- `TopLevelStatements`: move top-level statements into a synthetic class. For example,
```
class C {
  public constructor() {}
}

let x = 33

function f(): int {
  return x
}
```
becomes 
```
class C {
  public constructor() {}
}

abstract class ETSGLOBAL {
  public static main() {}

  public static _$init$_() {
    x = 33;
  }

  public static x = 33;

  public static f(): int {
    return x;
  }


  public static _$trigger_cctor$_() {}

}
```

- `DefaultParameterLowering`: handle functions with default parameters
```
class C {
  f(x: string = "oh") {}
}
```
converts into
```
class C {
  public f() {
    this.f("oh");
  }

  public f(x: string) {}
}
```

- `AmbientLowering` creates getter and setter for each indexer method in ambient classes (14.3.1 spec point), e.g.:
```
declare class A  {
  [index: number]: string  // indexer declaration
}
```
is converted to:
```
declare class A  {
  $_get(index: number): string
  $_set(index: number, value: string): void
}
```

- `ScopesInitPhase`: create `Scope` structures for all scopes; create `Variable` structures for every class name, function name and variable name in the program

- `OptionalLowering`: handle `a?.f` constructions
```
c?.f()
```
